60	        String region = Locality.of(owner.getCity(), owner.getPostcode());
61	        int fiscalYearSegment = FiscalYear.yearSegment(RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate()));
62	        String memberId = MemberId.of(region, fiscalYearSegment, owner.getTelephone(), owner.getLastName());
63	        return deduplicate(memberId);
