21	/**
22	 * The owner member-id format {@code '<REGION><FY><HASH8><CHK>'}: the owner's canonical region, the
23	 * two-digit fiscal year of its registration date, {@code HASH8} — the first 8 upper-case hex
24	 * characters of SHA-256 over the owner's normalized telephone concatenated with its last name — and
25	 * a single Luhn {@code CHK} check digit computed over the digits of {@code '<REGION><FY><HASH8>'}.
26	 *
27	 * <p>The member id is a stable identity derived purely from owner fields, with no sequence numbers,
28	 * so every value the application builds from it (the {@linkplain #fiscalYearSegmentOf(String) fiscal
29	 * year} and the owner's {@linkplain #regionOf(String) locality}) follows from the same identity.
30	 * This class owns that format: it builds a member id and reads its region and fiscal-year segments
31	 * back. The region, fiscal year and check-digit segments carry no separators, so the region and
32	 * fiscal year are read back by their fixed offsets from the end of the identity; a {@code '-<n>'}
33	 * suffix appended to de-duplicate a colliding id is the only separator that ever appears.
34	 */
35	public final class MemberId {
36	
37	    /** Number of leading hex characters of the digest kept as {@code HASH8}. */
38	    private static final int HASH_LENGTH = 8;
39	
40	    /** Number of digits in the two-digit fiscal-year segment. */
41	    private static final int FISCAL_YEAR_LENGTH = 2;
42	
43	    /** Number of Luhn check digits appended as {@code CHK}. */
44	    private static final int CHECK_LENGTH = 1;
45	
46	    /** Combined length of the {@code '<FY><HASH8><CHK>'} part that trails the region. */
47	    private static final int TRAILING_LENGTH = FISCAL_YEAR_LENGTH + HASH_LENGTH + CHECK_LENGTH;
48	
49	    /** Separator introduced only to disambiguate a colliding member id. */
50	    private static final char COLLISION_SEPARATOR = '-';
51	
52	    private MemberId() {
53	    }
54	
55	    /**
56	     * Build the {@code '<REGION><FY><HASH8><CHK>'} member id for the given region and identity inputs.
57	     *
58	     * @param region              the owner's canonical region
59	     * @param fiscalYearSegment   the two-digit segment of the owner's registration fiscal year
60	     * @param normalizedTelephone the owner's normalized (E.164) telephone
61	     * @param lastName            the owner's last name
62	     * @return the member id
63	     */
64	    public static String of(String region, int fiscalYearSegment, String normalizedTelephone, String lastName) {
65	        String base = region
66	            + String.format("%0" + FISCAL_YEAR_LENGTH + "d", fiscalYearSegment)
67	            + Sha256.hexPrefix(normalizedTelephone + lastName, HASH_LENGTH);
68	        return base + Luhn.checkDigit(base);
69	    }
70	
71	    /**
72	     * Return the region component of a member id — everything preceding the fixed-length
73	     * {@code '<FY><HASH8><CHK>'} tail, ignoring any {@code '-<n>'} de-duplication suffix.
74	     *
75	     * @param memberId the member id (may be {@code null})
76	     * @return the region, or {@code null} when {@code memberId} is {@code null} or too short to carry one
77	     */
78	    public static String regionOf(String memberId) {
79	        String identity = identity(memberId);
80	        if (identity == null || identity.length() <= TRAILING_LENGTH) {
81	            return null;
82	        }
83	        return identity.substring(0, identity.length() - TRAILING_LENGTH);
84	    }
85	
86	    /**
87	     * Return the two-digit fiscal-year segment of a member id.
88	     *
89	     * @param memberId the member id (may be {@code null})
90	     * @return the fiscal-year segment, or {@code null} when {@code memberId} is {@code null} or too
91	     * short to carry one
92	     */
93	    public static Integer fiscalYearSegmentOf(String memberId) {
94	        String identity = identity(memberId);
95	        if (identity == null || identity.length() <= TRAILING_LENGTH) {
96	            return null;
97	        }
98	        int start = identity.length() - TRAILING_LENGTH;
99	        return Integer.parseInt(identity.substring(start, start + FISCAL_YEAR_LENGTH));
100	    }
101	
102	    /**
103	     * The identity portion of a member id: the part before any {@code '-<n>'} de-duplication suffix.
104	     */
105	    private static String identity(String memberId) {
106	        if (memberId == null) {
107	            return null;
108	        }
109	        int separator = memberId.indexOf(COLLISION_SEPARATOR);
110	        return separator < 0 ? memberId : memberId.substring(0, separator);
111	    }
112	}
