17	package org.springframework.samples.petclinic.model;
18	
19	import org.springframework.samples.petclinic.util.Luhn;
20	import org.springframework.samples.petclinic.util.Sha256;
21	
22	/**
23	 * The owner member-id format {@code '<REGION><FY><HASH8><CHK>'}: the owner's canonical region, the
24	 * two-digit fiscal year of its registration date, {@code HASH8} — the first 8 upper-case hex
25	 * characters of SHA-256 over the owner's normalized telephone concatenated with its last name — and
26	 * a single Luhn {@code CHK} check digit computed over the digits of {@code '<REGION><FY><HASH8>'}.
27	 *
28	 * <p>The member id is a stable identity derived purely from owner fields, with no sequence numbers,
29	 * so every value the application builds from it (the {@linkplain #fiscalYearSegmentOf(String) fiscal
30	 * year} and the owner's {@linkplain #regionOf(String) locality}) follows from the same identity.
31	 * This class owns that format: it builds a member id and reads its region and fiscal-year segments
32	 * back. The region, fiscal year and check-digit segments carry no separators, so the region and
33	 * fiscal year are read back by their fixed offsets from the end of the identity; a {@code '-<n>'}
34	 * suffix appended to de-duplicate a colliding id is the only separator that ever appears.
35	 */
36	public final class MemberId {
37	
38	    /** Number of leading hex characters of the digest kept as {@code HASH8}. */
39	    private static final int HASH_LENGTH = 8;
40	
41	    /** Number of digits in the two-digit fiscal-year segment. */
42	    private static final int FISCAL_YEAR_LENGTH = 2;
43	
44	    /** Number of Luhn check digits appended as {@code CHK}. */
45	    private static final int CHECK_LENGTH = 1;
46	
47	    /** Combined length of the {@code '<FY><HASH8><CHK>'} part that trails the region. */
48	    private static final int TRAILING_LENGTH = FISCAL_YEAR_LENGTH + HASH_LENGTH + CHECK_LENGTH;
49	
50	    /** Separator introduced only to disambiguate a colliding member id. */
51	    private static final char COLLISION_SEPARATOR = '-';
52	
53	    private MemberId() {
54	    }
55	
56	    /**
57	     * Build the {@code '<REGION><FY><HASH8><CHK>'} member id for the given region and identity inputs.
58	     *
59	     * @param region              the owner's canonical region
60	     * @param fiscalYearSegment   the two-digit segment of the owner's registration fiscal year
61	     * @param normalizedTelephone the owner's normalized (E.164) telephone
62	     * @param lastName            the owner's last name
63	     * @return the member id
64	     */
65	    public static String of(String region, int fiscalYearSegment, String normalizedTelephone, String lastName) {
66	        String base = region
67	            + String.format("%0" + FISCAL_YEAR_LENGTH + "d", fiscalYearSegment)
68	            + Sha256.hexPrefix(normalizedTelephone + lastName, HASH_LENGTH);
69	        return base + Luhn.checkDigit(base);
70	    }
71	
72	    /**
73	     * Return the region component of a member id — everything preceding the fixed-length
74	     * {@code '<FY><HASH8><CHK>'} tail, ignoring any {@code '-<n>'} de-duplication suffix.
75	     *
76	     * @param memberId the member id (may be {@code null})
77	     * @return the region, or {@code null} when {@code memberId} is {@code null} or too short to carry one
78	     */
79	    public static String regionOf(String memberId) {
80	        String identity = identity(memberId);
81	        if (identity == null || identity.length() <= TRAILING_LENGTH) {
82	            return null;
83	        }
84	        return identity.substring(0, identity.length() - TRAILING_LENGTH);
85	    }
86	
87	    /**
88	     * Return the two-digit fiscal-year segment of a member id.
89	     *
90	     * @param memberId the member id (may be {@code null})
91	     * @return the fiscal-year segment, or {@code null} when {@code memberId} is {@code null} or too
92	     * short to carry one
93	     */
94	    public static Integer fiscalYearSegmentOf(String memberId) {
95	        String identity = identity(memberId);
96	        if (identity == null || identity.length() <= TRAILING_LENGTH) {
97	            return null;
98	        }
99	        int start = identity.length() - TRAILING_LENGTH;
100	        return Integer.parseInt(identity.substring(start, start + FISCAL_YEAR_LENGTH));
101	    }
102	
103	    /**
104	     * The identity portion of a member id: the part before any {@code '-<n>'} de-duplication suffix.
105	     */
106	    private static String identity(String memberId) {
107	        if (memberId == null) {
108	            return null;
109	        }
110	        int separator = memberId.indexOf(COLLISION_SEPARATOR);
111	        return separator < 0 ? memberId : memberId.substring(0, separator);
112	    }
113	}
