130	package org.springframework.samples.petclinic.model;
131	
132	import java.util.Map;
133	
134	/**
135	 * The fixed postcode-range-to-region lookup.
136	 *
137	 * <p>Maps each region to its inclusive 4-digit postcode range
138	 * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) and
139	 * answers the two questions the application asks of that single table: which
140	 * region a postcode falls in, and whether a region has a known range at all.
141	 * The ranges are disjoint, so a postcode belongs to at most one region.
142	 */
143	public final class PostcodeRegion {
144	
145	    /** Region -> inclusive 4-digit postcode range {@code {low, high}}. */
146	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
147	        "NSW", new int[] {2000, 2099},
148	        "VIC", new int[] {3000, 3099},
149	        "QLD", new int[] {4000, 4099});
150	
151	    private PostcodeRegion() {
152	    }
153	
154	    /**
155	     * Return the region whose range contains the given postcode, or {@code null}
156	     * when the postcode is absent, non-numeric, or in no known range.
157	     *
158	     * @param postcode the postcode to look up (may be {@code null} or blank)
159	     * @return the region string, or {@code null}
160	     */
161	    public static String regionFor(String postcode) {
162	        if (postcode == null || postcode.isBlank()) {
163	            return null;
164	        }
165	        int value;
166	        try {
167	            value = Integer.parseInt(postcode.trim());
168	        }
169	        catch (NumberFormatException ex) {
170	            return null;
171	        }
172	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
173	            int[] range = entry.getValue();
174	            if (value >= range[0] && value <= range[1]) {
175	                return entry.getKey();
176	            }
177	        }
178	        return null;
179	    }
180	
181	    /**
182	     * Return whether the given region has a known postcode range.
183	     *
184	     * @param region the region to check (may be {@code null})
185	     * @return {@code true} when the region has a range, {@code false} otherwise
186	     */
187	    public static boolean hasRange(String region) {
188	        return REGION_POSTCODES.containsKey(region);
189	    }
190	}
