258	 *
259	 * <p>The {@code TIER} is {@code PREMIUM} when the owner's membership level is
260	 * {@value #PREMIUM_MIN_LEVEL} or more, otherwise {@code STANDARD}. The
261	 * {@code AREA} is {@code METRO} when the owner's locality is one of the known
262	 * metro regions ({@code NSW}, {@code VIC} or {@code QLD}), otherwise
263	 * {@code REGIONAL}.
264	 */
265	public final class OwnerSegment {
266	
267	    /** Membership level at or above which an owner is in the {@code PREMIUM} tier. */
268	    private static final int PREMIUM_MIN_LEVEL = 3;
269	
270	    /** The localities classified as {@code METRO}; any other locality is {@code REGIONAL}. */
271	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
272	
273	    private OwnerSegment() {
274	    }
275	
276	    /**
277	     * Return the {@code '<TIER>_<AREA>'} segment for the given membership level and
278	     * locality.
279	     *
280	     * @param membershipLevel the owner's membership level (may be {@code null})
281	     * @param locality the owner's canonical region (may be {@code null})
282	     * @return one of {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"},
283	     * {@code "STANDARD_METRO"} or {@code "STANDARD_REGIONAL"}
284	     */
285	    public static String of(Integer membershipLevel, String locality) {
286	        return tier(membershipLevel) + "_" + area(locality);
287	    }
288	
289	    private static String tier(Integer membershipLevel) {
290	        return membershipLevel != null && membershipLevel >= PREMIUM_MIN_LEVEL ? "PREMIUM" : "STANDARD";
291	    }
292	
293	    private static String area(String locality) {
294	        return METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
295	    }
296	}
