412	package org.springframework.samples.petclinic.model;
413	
414	import java.time.LocalDate;
415	import java.time.Period;
416	
417	/**
418	 * A person's age band on a reference date: {@link #MINOR} (under 18),
419	 * {@link #ADULT} (18 to 64) or {@link #SENIOR} (65 or older).
420	 *
421	 * <p>This enum owns the age-to-band classification: given a birth date and the
422	 * date to measure against, it computes the completed-years age and maps it to
423	 * the band that age falls in.
424	 */
425	public enum AgeBand {
426	
427	    MINOR,
428	    ADULT,
429	    SENIOR;
430	
431	    /** Youngest age, in completed years, that counts as an adult rather than a minor. */
432	    private static final int ADULT_AGE = 18;
433	
434	    /** Youngest age, in completed years, that counts as a senior. */
435	    private static final int SENIOR_AGE = 65;
436	
437	    /**
438	     * Classify the age band for someone born on {@code birthDate} as measured on
439	     * {@code referenceDate}.
440	     *
441	     * @param birthDate     the date of birth, or {@code null} when unknown
442	     * @param referenceDate the date to measure the age against, or {@code null} when unknown
443	     * @return the age band, or {@code null} when either date is {@code null}
444	     */
445	    public static AgeBand on(LocalDate birthDate, LocalDate referenceDate) {
446	        if (birthDate == null || referenceDate == null) {
447	            return null;
448	        }
449	        int age = Period.between(birthDate, referenceDate).getYears();
450	        if (age < ADULT_AGE) {
451	            return MINOR;
452	        }
453	        if (age < SENIOR_AGE) {
454	            return ADULT;
455	        }
456	        return SENIOR;
457	    }
458	}
