public class HouseholdMembershipLevelCeiling {

    private final HouseholdMembers householdMembers;

    public HouseholdMembershipLevelCeiling(HouseholdMembers householdMembers) {
        this.householdMembers = householdMembers;
    }

    public Integer ceilingFor(Owner owner) {
        return householdMembers.of(owner).stream()
            .map(Owner::getMembershipLevel)
            .max(Integer::compareTo)
            .map(max -> max + 1)
            .orElse(null);
    }
}
===== PossibleDuplicateDetector =====
public class PossibleDuplicateDetector {

    private final OwnerRepository ownerRepository;

    public PossibleDuplicateDetector(OwnerRepository ownerRepository) {
        this.ownerRepository = ownerRepository;
    }

    public Owner findPossibleDuplicate(Owner owner) {
        if (owner.getPostcode() == null) {
            return null;
        }
        String lastNameCode = Soundex.encode(owner.getLastName());
        String identityKey = owner.getIdentityKey();
        return ownerRepository.findAll().stream()
            .filter(other -> !other.isDeleted())
            .filter(other -> owner.getPostcode().equals(other.getPostcode()))
            .filter(other -> Soundex.encode(other.getLastName()).equals(lastNameCode))
            .filter(other -> !Objects.equals(identityKey, other.getIdentityKey()))
            .min(Comparator.comparing(Owner::getId))
            .orElse(null);
    }
}
===== HouseholdMembers =====
public class HouseholdMembers {

    private final OwnerRepository ownerRepository;

    public HouseholdMembers(OwnerRepository ownerRepository) {
        this.ownerRepository = ownerRepository;
    }

    public List<Owner> of(Owner owner) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return List.of();
        }
        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
            .filter(other -> householdId.equals(other.getHouseholdId()))
            .toList();
    }
}

